// --- Step 1: Extract the Meal Data from the Tool Call ---

// This regular expression is specifically designed to capture the data
// from the <call:appendMealData "description", calories, protein, carbs, fat> format.
const toolCallRegex = /<call:appendMealData "([^"]+)",\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+)>/;

const match = aiOutput.match(toolCallRegex);

// If the regex finds a successful match, it will have 6 parts.
// We then build a clean JSON object from the captured parts.
if (match && match.length === 6) {
  finalData.mealData = {
    Meal_Description: match[1],
    Calories: parseInt(match[2], 10),
    Protein: parseInt(match[3], 10),
